#include "estimate.h"
#include <QStringList>

int parseEstimate(const QString &text)
{
    if (text.trimmed().isEmpty())
        return -1;

    int total = 0;
    const QStringList parts = text.split(' ', Qt::SkipEmptyParts);
    for (const QString &part : parts) {
        if (part.isEmpty())
            return -1;
        const QChar unit = part.back();
        const QString numStr = part.left(part.size() - 1);
        if (numStr.isEmpty())
            return -1;
        bool ok = false;
        const int value = numStr.toInt(&ok);
        if (!ok || value < 0)
            return -1;
        if (unit == 'w')
            total += value * 5 * 8 * 60;
        else if (unit == 'd')
            total += value * 8 * 60;
        else if (unit == 'h')
            total += value * 60;
        else if (unit == 'm')
            total += value;
        else
            return -1;
    }
    return total;
}

QString formatEstimate(int minutes)
{
    if (minutes < 0)
        return QString();

    QStringList out;
    const int weeks = minutes / (5 * 8 * 60);
    if (weeks)
        out << QString::number(weeks) + "w";
    const int remaining = minutes % (5 * 8 * 60);
    const int hours = remaining / 60;
    if (hours)
        out << QString::number(hours) + "h";
    const int mins = remaining % 60;
    out << QString::number(mins) + "m";
    return out.join(' ');
}
